 CREATE OR REPLACE FUNCTION public.detentionshelterauthorizationbs(i_intakenumber character varying)                                                                                                                                                                                                                                                         
  RETURNS TABLE(persons text, evaluationfields text, youthname character varying, youthid character varying, race character varying, provider_name character varying, provider_address character varying, provider_number character varying, court_address character varying, admission_date timestamp without time zone, placement_reason character varying)
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                           
 AS $function$                                                                                                                                                                                                                                                                                                                                             
         DECLARE                                                                                                                                                                                                                                                                                                                                           
          BEGIN                                                                                                                                                                                                                                                                                                                                            
         RETURN QUERY                                                                                                                                                                                                                                                                                                                                      
           (select                                                                                                                                                                                                                                                                                                                                         
           cast(idas.jsondata->>'persons' as text) as persons,                                                                                                                                                                                                                                                                                             
           cast(idas.jsondata->>'evaluationFields' as text) as evaluationfields,                                                                                                                                                                                                                                                                           
           cast(p.firstname ||' '|| p.lastname as character varying) as youthname,                                                                                                                                                                                                                                                                         
           cast (p.cjamspid as character varying)as youthid,                                                                                                                                                                                                                                                                                               
       (select distinct typedescription from racetype where racetypekey=p.racetypekey) as race,                                                                                                                                                                                                                                                            
                 cast(pr.providername as character varying) as provider_name,                                                                                                                                                                                                                                                                              
         cast(paddr.buildingno||','||paddr.addressline1||','|| paddr.addressline2||','||paddr.city||','||paddr.state  as character varying) as provider_address,                                                                                                                                                                                           
         cast(pcinfo.phonenumber as character varying) as provider_number,                                                                                                                                                                                                                                                                                 
         cast('MD Court,111 Court Street,Baltimore, MD 22222,(410) 410-4100' as character varying) as court_address,                                                                                                                                                                                                                                       
         cast(pl.addate as timestamp without time zone) as admission_date,                                                                                                                                                                                                                                                                                 
         cast(pprt.description as character varying) as placement_reason                                                                                                                                                                                                                                                                                   
        from                                                                                                                                                                                                                                                                                                                                               
        intakedastaging idas                                                                                                                                                                                                                                                                                                                               
            join person p on idas.focuspersonid=p.personid and p.activeflag=1                                                                                                                                                                                                                                                                              
             left join placement pl on idas.intakenumber =pl.intakenumber and pl.activeflag=1                                                                                                                                                                                                                                                              
             left join placementprimaryadmissionreasontype pprt on pl.placementprimaryadmissionreasontypekey = pprt.placementprimaryadmissionreasontypekey and pprt.activeflag=1                                                                                                                                                                           
                 left join provider pr ON pl.providerid = pr.providerid AND pr.activeflag=1                                                                                                                                                                                                                                                                
         LEFT JOIN provideraddress paddr ON pr.providerid = paddr.providerid AND paddr.activeflag=1                                                                                                                                                                                                                                                        
         LEFT JOIN providercontactinfo pcinfo ON pr.providerid = pcinfo.providerid AND pcinfo.activeflag = 1                                                                                                                                                                                                                                               
        where  idas.intakenumber = i_intakenumber) ;                                                                                                                                                                                                                                                                                                       
    end;                                                                                                                                                                                                                                                                                                                                                   
  $function$                                                                                                                                                                                                                                                                                                                                                 

